  AwakerTalent_122607_TalentDesc_1 = {
    Text = "প্রতি 2টি 「স্ট্রাইক」 কার্ড খেলার পর, মুশেট একটি অনুসন্ধান সম্পাদন করে, এলোমেলোভাবে 1 বার ক্ষতি করে, যার পরিমাণ মুশেট-এর ATK-এর 30%(এটি 「স্ট্রাইক」 হিসেবে গণ্য হবে)। এই প্রভাব প্রতি টার্নে সর্বোচ্চ 4 বার পর্যন্ত সক্রিয় হতে পারে।"
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "নাটকীয় সাক্ষাৎ"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「তারার অধ্যায়」 স্তরে কার্যকর।\n·এই জাগরণকারীর CON, আক্রমণ, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার নসিস জাগরণ খেলার পর [Arg2] পয়েন্ট S-শক্তি অর্জন করে।\n·সকল জাগরণকারীর বিষক্রিয়া প্রভাব ট্রিগার করলে [Arg3]％ বৃদ্ধি পায়।\n·প্রতিটি স্তরের 「মোহমত্ত」 অতিরিক্তভাবে 「মানবাকৃতি」 শত্রুর দেওয়া ক্ষতি 1％ হ্রাস করে, এবং অপসারণের সময় অতিরিক্তভাবে 「মানবাকৃতি」 শত্রুর উপর সর্বোচ্চ জীবনী শক্তির 1％ বিশুদ্ধ ক্ষতি প্রদান করে।"
  },
