  },
  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·দলে অ্যারাকনি থাকলে, 「আল্ট্রা」 রিয়েল্ম 「সিঙ্গুলারিটি·অতিমাত্রিক」 রিয়েল্মে প্রতিস্থাপিত হবে।\n·মাত্রা পরিভ্রমণ: প্রতি রাউন্ডে প্রথমবার কমান্ড কার্ড খেলার পর এই প্রভাব সক্রিয় হয়, সেটির অস্থায়ী মূল প্রতিলিপি অতিমাত্রিক স্থানে রাখা হয় এবং সেটি ও অস্থায়ী প্রতিলিপিকে ২৫ স্তর 「সিঙ্গুলারিটি বীকন」 প্রদান করা হয়, আল্ট্রা রাউন্ডে এই প্রভাব সক্রিয় করা যাবে না।\n·সিঙ্গুলারিটি বীকন: প্রতি ১ স্তর থাকলে এই কার্ডের ক্ষতি, স্থির শক্তি ও শুঁড় ক্ষতি বৃদ্ধি, স্থির বিষক্রিয়া, স্থির পাল্টা আঘাতের চূড়ান্ত প্রভাব ২% বৃদ্ধি পায়, স্থির শিল্ড, স্থির জীবন নিরাময়, STR▼ এর চূড়ান্ত প্রভাব ১% বৃদ্ধি পায়, খেলার পর সরিয়ে দেওয়া হয়। সিঙ্গুলারিটি বীকন সহ কার্ড 「মাত্রা পরিভ্রমণ」 সক্রিয় করতে পারবে না।\n·অতিমাত্রিক স্থান: অতিমাত্রিক স্থান সীমায় পৌঁছালে রাউন্ড শেষে পরিবর্তে অতিমাত্রিক স্থান সক্রিয় হয়: আর অতিরিক্ত রাউন্ড পাওয়া যাবে না, সংরক্ষিত নয় এমন হাতের কার্ড ফেলে দেওয়া হয় এবং মায়া প্রভাব সক্রিয় হয়, অতিমাত্রিক স্থানের সকল কার্ড হাতে রাখা হয়, বর্তমান অ্যারিথমেটিকা ৫ পয়েন্টে নির্ধারিত হয়। অতিমাত্রিক স্থান সক্রিয় হওয়ার পর, এই রাউন্ড আল্ট্রা রাউন্ড হিসেবে গণ্য হয়।\n·「সিঙ্গুলারিটি বিলয়」: অতিমাত্রিক স্থানের সবচেয়ে বাম দিকের কার্ড বের করো। ৩ রাউন্ড কুলডাউন।\n·অন্বেষণ শুরুর পর দলের ক্ষতি বর্ধন +৫০%, এবং ১৫ স্তর 「সিঙ্গুলারিটি প্রিজম」 অর্জন করো।\n·「সিঙ্গুলারিটি প্রিজম」: সকল কমান্ড কার্ড সমপরিমাণ সিঙ্গুলারিটি বীকনের বোনাস সহ গণ্য হয়।\n·অতিমাত্রিক দক্ষতা: দলে প্রতি ১ পয়েন্ট রিয়েল্ম দক্ষতা থাকলে 「সিঙ্গুলারিটি প্রিজম」 এবং 「মাত্রা পরিভ্রমণ」 প্রদত্ত 「সিঙ্গুলারিটি বীকন」 স্তর সংখ্যা ০.০৫％ বৃদ্ধি পায়।\n·বিশুদ্ধতম অতিমাত্রা: যদি দল শুধুমাত্র আল্ট্রা বা বিশৃঙ্খলা জাগরণকারী দ্বারা গঠিত হয়, অতিমাত্রিক দক্ষতার প্রভাব এবং রিয়েল্ম প্রদত্ত ক্ষতি বর্ধন দ্বিগুণ হয়।"
  },
