  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「নক্ষত্র অধ্যায়」স্তরে কার্যকর হয়।\n·এই জাগরণকারীর CON, ATK, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার জাগরণ খেলার পর [Arg2] পয়েন্ট S-শক্তি পায়।\n·「সায়ার গান」নির্বাচিত জাগরণকারী [Arg3] স্তর「প্রজনন উৎসব」পায়, এবং পরবর্তী পসি 2 বার কার্যকর হয়।\n·সায়া「কারো」শত্রুদের উপর প্রয়োগ করা「ক্ষয়」অতিরিক্ত [Arg4]% বৃদ্ধি পায়।"
  },
