  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「তারার অধ্যায়」 স্তরে কার্যকর।\n·এই জাগরণকারীর CON, আক্রমণ, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার জাগরণ খেলার পর [Arg2] পয়েন্ট S-শক্তি অর্জন করে।\n·「অসীম বন্য ছায়া」 STR▼ প্রভাব সৃষ্টি করে, অর্জিত শক্তির গুণক [Arg3]% বৃদ্ধি পায়, প্রতিবার কার্যকর হলে পরবর্তী 「পাপরঞ্জিত বন্দুকের ফলা」 অতিরিক্ত [Arg4]% শক্তি বোনাস উপভোগ করে, সর্বোচ্চ ১২০০%।"
  },
