  AwakerTalent_130920_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「তারার অধ্যায়」 স্তরে কার্যকর।\n·এই জাগরণকারীর CON, আক্রমণ, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার নসিস জাগরণ খেলার পর [Arg2] পয়েন্ট S-শক্তি অর্জন করে।\n·「ঘূর্ণি! প্রবাহ! গোলা!」 নির্দিষ্ট ক্ষতি [Arg3]％ বৃদ্ধি পায়।\n·মস এক্সাল্ট প্রকাশের আগে লক্ষ্যের 「সুদৃঢ়」 ও 「অস্থায়ী সুদৃঢ়」 প্রভাব অপসারণ করে, সফলভাবে অপসারণ হলে এই এক্সাল্টের ক্রিটিক্যাল ড্যামেজ + [Arg4]％।"
