  AwakerTalent_131854_TalentDesc_1 = {
    Text = "·সায়া দলে থাকলে, 「কারো」 রিয়েল্ম 「প্রজনন · মাংস」 রিয়েল্ম দ্বারা প্রতিস্থাপিত হয়।\n·ভ্রূণ সংমিশ্রণ: প্রতি রাউন্ডে অর্জিত ভ্রূণ সংমিশ্রণ ৫০~১০০-এ উন্নীত হয়, হারানো জীবনের সাথে বৃদ্ধি পায়, কিন্তু ভ্রূণ সংমিশ্রণ সীমা ১০০ থেকে ২০০-তে উন্নীত হয়, সীমায় পৌঁছালে 「প্রজনন ভ্রূণ」 হাতে রাখা হয়।\n·প্রজনন ভ্রূণ: খেলার সময় আর ক্রিটিক্যাল হার অর্জন করা যাবে না, গ্রাস করলেও আর শিল্ড ও অস্থায়ী STR অর্জন করা যাবে না। প্রতি জাগরণকারী প্রতি রাউন্ডে প্রথমবার 「প্রজনন ভ্রূণ」 ব্যবহার করলে ৪০ স্তর 「প্রজনন উৎসব」 অর্জন করে: প্রতি ১ স্তর থাকলে সেই জাগরণকারীর এই রাউন্ডে পরবর্তী এক্সাল্ট থেকে সৃষ্ট ক্ষতি, নির্দিষ্ট শিল্ড, নির্দিষ্ট জীবন নিরাময়, নির্দিষ্ট শক্তি, STR▼, শুঁড় ক্ষতি বৃদ্ধি, নির্দিষ্ট বিষক্রিয়া, নির্দিষ্ট পাল্টা আঘাতের চূড়ান্ত প্রভাব ১％ বৃদ্ধি পায়।\n·রক্তিম চুল্লি: রাউন্ড শুরুতে স্বয়ংক্রিয় সঞ্চয়ের পরিমাণ ১০% হারানো জীবনে পরিবর্তিত হয়, সর্বোচ্চ সঞ্চয়ের পরিমাণ ৫০% সর্বোচ্চ জীবনী শক্তিতে পরিবর্তিত হয়। যুদ্ধ শেষে আর সঞ্চয় হবে না, ব্যবহারের সময় ৩ রাউন্ড কুলডাউন থাকে।\n·স্কারলেট ক্ষয়: রক্তিম চুল্লি ব্যবহারের পর সকল শত্রুর উপর লক্ষ্যের সর্বোচ্চ জীবনী শক্তির ১% ক্ষয় আরোপ করে, যত বেশি রক্তিম চুল্লি ব্যবহার করা হবে ক্ষয়ের প্রভাব তত শক্তিশালী হবে, সর্বোচ্চ ১০০% বৃদ্ধি পাবে। 「খোলস」 শত্রুর উপর ৫ গুণ ক্ষয়ের প্রভাব আরোপ করে।\n·অন্বেষণ শুরুর পর, সর্বোচ্চ জীবনী শক্তি ১০％ বৃদ্ধি পায়, দলের ক্ষতি বর্ধন +৫০%, প্রতি রাউন্ড শুরুতে সকল জাগরণকারী ২০ স্তর 「প্রজনন উৎসব」 অর্জন করে। দল শুধুমাত্র কারো বা বিশৃঙ্খলা জাগরণ সত্তা দ্বারা গঠিত হলে, এই প্রভাব থেকে প্রাপ্ত ক্ষতি বর্ধন দ্বিগুণ হয়।\n·রিয়েল্ম দক্ষতা 「প্রজনন·রক্তমাংস দক্ষতা」তে পরিণত হয়, প্রতি পয়েন্ট রিয়েল্ম দক্ষতা 「প্রজনন · মাংস」 থেকে অর্জিত 「প্রজনন উৎসব」 ০.০৫% বৃদ্ধি করে। \n·দল শুধুমাত্র কারো বা বিশৃঙ্খলা জাগরণ সত্তা দ্বারা গঠিত হলে, 「প্রজনন·রক্তমাংস দক্ষতা」 প্রভাব দ্বিগুণ হয়।"
  },
