  },
  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「নক্ষত্র অধ্যায়」 স্তরে কার্যকর হয়।\n·এই জাগরণকারীর CON, ATK, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার জাগরণ খেলার পরে [Arg2] পয়েন্ট S-শক্তি অর্জন করে।\n·「পন্টোস」 「আনন্দময় পরিবার」-এর উপর যে নির্দিষ্ট ক্ষতি করে তা [Arg3]％ বৃদ্ধি পায়।\n·「অবিরাম শিকার উৎসব」 প্রতি 10 পয়েন্ট অ্যালিমাস খরচ করলে [Arg4]％ আক্রমণ শক্তির শুঁড় ক্ষতি অর্জন করে, 「দুঃস্বপ্নের আক্রমণ」 ক্ষতি করার সময় লক্ষ্যের [Arg5]％ DEF-এর শক্তি অস্থায়ীভাবে হ্রাস করে।"
  },
