    Text = "·এই চরিত্র দলে থাকলে, 「অ্যাকুওর」 রিয়েল্ম 「অন্ধকার·গভীর সমুদ্র」 রিয়েল্ম দিয়ে প্রতিস্থাপিত হবে।\n·মৌলিক শুঁড় ক্ষতি দলের সর্বোচ্চ জীবনী শক্তির ৫%-এ পরিবর্তিত হয়।\n·অন্বেষণ শুরু হওয়ার পরে দলের ক্ষতি বর্ধন +৫০%, যদি দলটি শুধুমাত্র গভীর সমুদ্র বা বিশৃঙ্খলা জাগরণকারী দিয়ে গঠিত হয়, তাহলে এই প্রভাব থেকে অর্জিত ক্ষতি বর্ধন দ্বিগুণ হয়, কিন্তু যুদ্ধ শুরুতে আর অতিরিক্ত শুঁড় পাওয়া যাবে না।\n·「শুঁড় সমাবেশ」 প্রভাব আর থাকবে না।\n·শুঁড় ভঙ্গি 「অন্ধকার·শুঁড় ভঙ্গি」-তে পরিবর্তিত হয়।\n·「অন্ধকার·শান্ত সাগর」：সর্বোচ্চ জীবনী শক্তির ২৫% শিল্ড অর্জন করে, রাউন্ড শেষে শুঁড় আর আক্রমণ করে না, ৩ রাউন্ড কুলডাউন।\n·「অন্ধকার·প্রচণ্ড তরঙ্গ」：এই রাউন্ডে শুঁড় ক্ষতি ১২৫%-এ পরিণত হয়, সক্রিয় ক্ষতি করার পরে ১টি শুঁড় আক্রমণ করে, কিন্তু রাউন্ড শেষে ১টি শুঁড় হারায়, ৩ রাউন্ড কুলডাউন।\n·রিয়েল্ম দক্ষতা 「অন্ধকার·গভীর সমুদ্র দক্ষতা」-তে পরিবর্তিত হয়, প্রতি পয়েন্ট রিয়েল্ম দক্ষতায় 「অন্ধকার·শান্ত সাগর」-এর শিল্ড সর্বোচ্চ জীবনী শক্তির ০.০২৫% বৃদ্ধি পায়, 「অন্ধকার·প্রচণ্ড তরঙ্গ」-এর শুঁড় ক্ষতি অতিরিক্ত ০.০২৫% বৃদ্ধি পায়।\n·যদি দলটি শুধুমাত্র গভীর সমুদ্র বা বিশৃঙ্খলা জাগরণকারী দিয়ে গঠিত হয়, 「অন্ধকার·রিয়েল্ম দক্ষতা」 প্রভাব দ্বিগুণ হয়।"
  },
