  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「নক্ষত্র অধ্যায়」 স্তরে কার্যকর।\n·এই জাগরণকারীর CON, ATK, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগরণকারী প্রথমবার নসিস জাগরণ খেলার পর [Arg2] পয়েন্ট S-শক্তি অর্জন করে।\n·「সীমা-ভেদী তরবারি」 অতিরিক্ত [Arg3]％ শক্তি বোনাস উপভোগ করে, শত্রু হত্যার পর [Arg4] কালো মুদ্রা অর্জন করে, নিজের মুদ্রা প্রাপ্তি বোনাস উপভোগ করে, প্রতিটি যুদ্ধে সর্বোচ্চ ১ বার কার্যকর হয়।"
  },
