  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·দলে মরণ দ্বন্দ্ব·রোটান থাকলে, 「কেওস」 রিয়েল্ম 「আদিম বিশৃঙ্খলা」 রিয়েল্মে প্রতিস্থাপিত হয়।\n·আদিম সঞ্চার: মূল S-শক্তি ২০০০ পয়েন্টে বৃদ্ধি পায়, দলের ক্ষতি বর্ধন +৫০%, সকল জাগরণকারীর আক্রমণ ও প্রতিরক্ষা ১০% বৃদ্ধি পায়। যদি দল শুধুমাত্র বিশৃঙ্খলা জাগরণ সত্তা দ্বারা গঠিত হয়, তাহলে এই প্রভাব থেকে প্রাপ্ত ক্ষতি বর্ধন দ্বিগুণ হয়। যুদ্ধ শুরুতে ২০০০ পয়েন্ট S-শক্তি অর্জন করো।\n·সকল চাবির উৎস এক: সকল জাগরণকারীর রৌপ্য চাবি চার্জ স্তর দলের গড় মানে পরিণত হয়। এবং আর অ্যারিথমেটিকা ব্যয়ের মাধ্যমে S-শক্তি অর্জন করা যাবে না, বরং প্রতিটি জাগরণকারী প্রতি রাউন্ডে প্রথম কমান্ড কার্ড থেকে 「সেই জাগরণকারীর রৌপ্য চাবি চার্জ×৩+১০০」 পরিমাণ S-শক্তি অর্জন করবে।\n·অবিভক্ত রাজ্য: আর অন্য রিয়েল্মের বিশুদ্ধতম অতিমাত্রা, দক্ষতা প্রভাব দ্বিগুণ, শক্তিশালী প্রভাব দ্বিগুণ কার্যকর হবে না।\n·আদিম প্রতিধ্বনি: জাগরণ প্রস্তুতি ১ অর্জন করে, প্রতি রাউন্ডে প্রথমবার খেলার সময় স্বয়ংক্রিয়ভাবে বহনকৃত পসি মুক্ত করে।\n·স্মৃতির টুকরো: পসি 「আদিম·যমজ পুনরাবৃত্তি」 এবং 「আদিম·ত্রি-পর্যায় দিব্যজ্ঞান」 দ্বারা প্রতিস্থাপিত হয়, নিজে বহনকৃত পসি মুক্ত করা যাবে না।\n·আদিম · যমজ পুনরাবৃত্তি: হাতে থাকা পসি থেকে ৩ ধরনের পসি আবিষ্কার করো, ১টি পসি বেছে নাও এবং তা ২ বার কার্যকর করো।\n·আদিম · ত্রি-পর্যায় দিব্যজ্ঞান: হাতে থাকা পসি থেকে ৩ গ্রুপ পসি আবিষ্কার করো, প্রতিটি গ্রুপ ৩ ধরনের ভিন্ন পসি দ্বারা গঠিত, একটি গ্রুপ বেছে নাও এবং তার পসিগুলো পর্যায়ক্রমে ১ বার করে কার্যকর করো।\n·আদিম·যমজ পুনরাবৃত্তি এবং আদিম·ত্রি-পর্যায় দিব্যজ্ঞানের পসিতে আটটি 「আদিম স্মৃতি」 অন্তর্ভুক্ত থাকবে।\n·আদিম·যমজ পুনরাবৃত্তি এবং আদিম·ত্রি-পর্যায় দিব্যজ্ঞান শুধুমাত্র ১ বার পসি মুক্ত করা হিসেবে গণ্য হয়, একাধিকবার কার্যকর হলে শুধুমাত্র প্রথম কার্যকর পসির জন্য প্রযোজ্য।\n·রিয়েল্ম দক্ষতা 「আদিম·বিশৃঙ্খলা দক্ষতা」তে পরিণত হয়, প্রতি পয়েন্ট রিয়েল্ম দক্ষতা পসির শক্তি ০.০৫% বৃদ্ধি করে।\n·প্রতি পয়েন্ট পসি শক্তি পসির দ্বারা সৃষ্ট স্থির বিষক্রিয়া, স্থির পাল্টা আঘাত, স্থির শক্তি, স্থির শুঁড় ক্ষতি, স্থির অতীতের অঙ্গার ২%, স্থির শিল্ড, স্থির জীবন নিরাময়, STR▼, ক্রিটিক্যাল হার, ক্রিটিক্যাল ড্যামেজ, ক্ষতি বর্ধন, রিয়েল্ম দক্ষতা, অ্যালিমাস, ভ্রূণ সংমিশ্রণ, S-শক্তি ১% বৃদ্ধি করে।\n·যদি দল শুধুমাত্র বিশৃঙ্খলা জাগরণ সত্তা দ্বারা গঠিত হয়, 「আদিম·বিশৃঙ্খলা দক্ষতা」 প্রভাব দ্বিগুণ হয়।"
