    Text = "Lily এবং তার সজ্জিত WoD ও কভেন্যান্ট-এর প্রতি 1% মৃত্যু প্রতিরোধের জন্য, 「কালো জলাভূমির নিষিদ্ধ অঞ্চল」 এবং 「Basic Defense」-এর মূল Shield 0.25% বৃদ্ধি পায়, এবং বস যুদ্ধে Endure-এর সঞ্চয় ও সীমা 0.25% বৃদ্ধি পায়।\nLily দলে থাকলে, প্রতিটি হারানো HP-এর জন্য 1 স্তর Endure অর্জন করো, যেখানে Endure স্তরের সীমা Max HP-এর সমান।"
  },
