  AwakerTalent_46445_TalentDesc_1 = {
    Text = "সালভাদোরের গলনচুল্লি নিরাময় HP পুনরুদ্ধার বৃদ্ধির সুবিধা পায়।"
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "আত্মার রাখাল"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "রামোনা অতিরিক্ত 2.5 কীফ্লেয়ার পুনরুৎপাদন বৈশিষ্ট্য পায়। প্রতিটি সমসংস্থান হার স্তরে রামোনা অতিরিক্ত 0.5 কীফ্লেয়ার পুনরুৎপাদন বৈশিষ্ট্য পায়।\nপ্রতিটি কীফ্লেয়ার পুনরুৎপাদন স্তরের জন্য 「রানির তরবারি」-র মূল ক্ষতি 1% বৃদ্ধি পায়, এবং ব্যবহার শেষে 0.75 অস্থায়ী রিয়েলম দক্ষতা অর্জন করো।"
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "হৃদয় ও রৌপ্যের অনুরণন"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "রামোনা: টাইমওর্ন অতিরিক্ত 2.5 কীফ্লেয়ার পুনরুৎপাদন গুণাবলি লাভ করে। প্রতিটি সমসংস্থান হার স্তর অতিরিক্তভাবে রামোনা: টাইমওর্ন-কে 0.5 কীফ্লেয়ার পুনরুৎপাদন গুণাবলি প্রদান করে।\nপ্রতিটি কীফ্লেয়ার পুনরুৎপাদন স্তর গুণাবলির জন্য, 「বেসিক স্ট্রাইক」-এর লুপ প্রভাব রামোনা: টাইমওর্ন-কে 0.2% ক্রিটিক্যাল হার প্রদান করে, এবং 「বেসিক ডিফেন্স」-এর লুপ প্রভাব রামোনা: টাইমওর্ন-কে 0.2 অ্যালিমাস প্রদান করে।"
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "হৃদয় ও রৌপ্যের অনুরণন"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "নটিলা যত 1টি করে রিয়েল্ম দক্ষতা গুণাবলি ধারণ করে, <Ready and set:\"প্রস্তুত ও উদ্যত\"> থেকে আসা পাল্টা আঘাতের ক্ষতি 0.25% করে বৃদ্ধি পায়।"
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "রক্ষণাবেক্ষণ"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "Nymphaea-র প্রতি 1% ক্ষতি বর্ধন গুণের জন্য, 「মৃত্যুঘণ্টার প্রতিধ্বনি」 এবং 「Passage of the Ego」 দ্বারা সৃষ্ট বেস Poison প্রভাব 0.5% বৃদ্ধি পায়।"
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "নিমজ্জন"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·যুদ্ধ শুরু হলে, হাতে 1টি 「আবেশ」 রাখা হয়।\n·মিরিয়ামের 「মৌলিক আঘাত」 100% তাঁবু ক্ষতি বোনাস উপভোগ করে।\n·মিরিয়াম জাগরণকারী নিজে, নিয়তিচক্র, কভেন্যান্ট প্রতি 1% ক্রিটিক্যাল ড্যামেজ প্রদান করলে, এক্সাল্টের শক্তি, শুঁড় ক্ষতি, অ্যালিমাস, প্রয়োগ এবং বিষক্রিয়া প্রভাব ট্রিগার 0.2% বৃদ্ধি পায়।"
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "অনির্বাণ ভক্তি"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "Tulu এবং তার সজ্জিত WoD & Covenant-এর প্রতিটি অ্যালিমাস পুনরুদ্ধার স্তরের জন্য, 「Strike」 +5% শুঁড় ক্ষতি এবং STR বোনাস পায়। 「Abyss Order」 15% শুঁড় ক্ষতি এবং STR ক্ষতি বৃদ্ধি পায়।"
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "দেবরাজের ক্ষমতা"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "সাঙ্গা এবং তার সজ্জিত WoD ও কভেন্যান্টের প্রতি 1% মৃত্যু প্রতিরোধের জন্য, 「Basic Strike」 এবং 「Basic Defense」 থেকে কার্ড খেলে অ্যালিমাস অর্জন 0.03 পয়েন্ট বৃদ্ধি পায়, এবং 「হারানো শিল্পকলা」 অতিরিক্ত 0.15% ক্রিট. রেট ও ক্ষতি বোনাস পায়।"
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "মৃত্যুর প্রবোধন"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "Doll‑এর প্রতি 1টি অ্যালিমাস পুনরুদ্ধার স্তর বৈশিষ্ট্যের জন্য, 「বহির্দেশীয় শল্যচিকিৎসা」 এবং 「Equivalent বিনিময় কেন্দ্রের মালিক」-এর HP পুনরুদ্ধার প্রভাব 0.5% করে বৃদ্ধি পায়।"
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "নসিস ডিকনস্ট্রাকশন"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "ওজিয়ারের প্রতি 1% মুদ্রা প্রাপ্তি অনুযায়ী, 「সপ্তকলা, সদ্গুণের উত্তরাধিকার」 থেকে প্রাপ্ত অস্থায়ী STR 3% করে বৃদ্ধি পায়।"
