  AwakerTalent_55109_TalentDesc_1 = {
    Text = "জেনকিন এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট থেকে প্রাপ্ত প্রতি 1% ক্রিটিক্যাল হারের জন্য, 「Basic Strike」 এবং 「Get 'em! Brown!」-এর মূল ক্ষতি 2% করে বৃদ্ধি পায়।"
