  AwakerTalent_55176_TalentDesc_1 = {
    Text = "এরিকা এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট যে প্রতিটি 1 স্তর কীফ্লেয়ার পুনরুৎপাদন স্তর প্রদান করে, তার জন্য 「তড়িৎচুম্বকীয় বিস্ফোরণ」 এরিকাকে 0.5% অস্থায়ী ক্রিটিক্যাল হার এবং ক্রিটিক্যাল ক্ষতি প্রদান করে।"
