  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "টার্নের শুরুতে, 1 স্তর স্বপ্নটোপ অর্জন করো।\n1 স্তর স্বপ্নটোপ ভোগ করলে, এই যুদ্ধে 「পথহারাদের রক্ষক」 এবং 「স্বপ্নের মৃতনগরী」-র কাউন্টার 5% ATK দ্বারা বৃদ্ধি পায়।\nওয়ান্ডা এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট যে প্রতি 1% ক্ষতি বর্ধন বৈশিষ্ট্য প্রদান করে, 「স্বপ্নের মৃতনগরী」-র কাউন্টার 0.75% করে বৃদ্ধি পায়।"
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "প্রত্যাদেশ"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "কাসিয়া এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট থেকে প্রাপ্ত প্রতি 1 রিয়েল্ম দক্ষতার জন্য, 「ম্যাজিক কার্নিভাল」 কাসিয়ার সব মূল ক্ষতি 0.2% করে বৃদ্ধি করে।"
  },
  AwakerTalent_55367_TalentName_1 = {
