  AwakerTalent_55507_TalentDesc_1 = {
    Text = "টিঙ্কট এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট থেকে প্রাপ্ত প্রতি 1% মুদ্রা প্রাপ্তির জন্য, 「Starlight Aurora」 অতিরিক্ত 0.15% অস্থায়ী ক্রিটিক্যাল হার অর্জন করে।"
