  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "হর্লার 「স্ট্রাইক」 ও 「ডিফেন্ড」 কমান্ড কার্ডগুলোকে গীতধর্মী স্তোত্র হিসেবে গণ্য করা হয়।\nযখন হর্লার কমান্ড কার্ডগুলো তাদের লীপ প্রভাব সক্রিয় করে, সে সেই স্তোত্রের সঙ্গে যুক্ত আবেগাবস্থায় প্রবেশ করে। হর্লা এক সময়ে কেবল একটি আবেগাবস্থায় থাকতে পারে, এবং অন্য কোনো স্তোত্রের লীপ প্রভাব সক্রিয় হলে আবেগাবস্থা বদলে সংশ্লিষ্ট আবেগে রূপান্তরিত হয়। প্রতিটি আবেগাবস্থার একটি দলব্যাপী প্যাসিভ বাফ থাকে, যা হর্লা সেই আবেগে থাকা পর্যন্ত সক্রিয় থাকে। প্রতিটি আবেগাবস্থা হর্লার এক্সাল্ট‑এর ভিন্ন একটি প্রভাবকে শক্তিশালী করে। আবেগাবস্থা পুরো অনুসন্ধান জুড়ে স্থায়ী থাকে।\nহর্লার প্রতি 1% মৃত্যু প্রতিরোধের জন্য, হর্লার বর্তমান আবেগাবস্থার প্যাসিভ প্রভাবের মান সমস্তের উৎস‑এর মূল মানের 0.1% করে বৃদ্ধি পায়।"
  },
