  AwakerTalent_56223_TalentDesc_1 = {
    Text = "সেলেস্ট একটি কমান্ড কার্ড ব্যবহার করার পর, 1টি শুঁড় শত্রুর ওপর আক্রমণ চালায়। সেলেস্ট, তার WoD এবং কভেন্যান্টের প্রতিটি রিয়েল্ম দক্ষতা পয়েন্টের জন্য, এই সক্রিয়করণ অতিরিক্ত 0.5% শুঁড়ের ক্ষতি করে।"
