  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·আগ্রিপা নিজে, সজ্জিত ফেট হুইল ও গোপন চুক্তি প্রতি 1% কালো মুদ্রা ড্রপ বৈশিষ্ট্য প্রদান করলে, 「ফ্যাকাশে আশীর্বাদ」-এর মৌলিক ঢাল 0.5% এবং মৌলিক বিষ 1% বৃদ্ধি পাবে।"
