  AwakerTalent_57567_TalentDesc_1 = {
    Text = "হেলটের প্রতি 1% ক্ষতি বর্ধন বৈশিষ্ট্যের জন্য, 「চরম সংকটে বেঁচে থাকা」 এই টার্নে হেলটের প্রদত্ত ক্ষতি 0.3% বৃদ্ধি করে।"
