  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·লেক শত্রু হত্যা করলে 5 কালো মুদ্রা পায়, লেকের প্রতি 1% কালো মুদ্রা ড্রপ থাকলে প্রাপ্তির পরিমাণ 1% বৃদ্ধি পায়, প্রতি অনুসন্ধানে সর্বাধিক 5 বার কার্যকর।\n·যুদ্ধের মাধ্যমে 50/125/250 কালো মুদ্রা অর্জনের পর, সৃষ্টি সীমা+1, যুদ্ধ শেষে একটি <C05_zaowu:「বিশৃঙ্খলার উত্তরাধিকার」> বেছে সৃষ্টি তালিকায় যোগ করুন।"
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "বিজয়ী সব নেয়"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "বস যুদ্ধে, টার্নের শুরুতে এবং 「ডল: ইনফার্নো」 এক্সাল্ট মুক্ত করার পর, 1 স্তর 「Finale」 অর্জন করুন। 「Finale」 সর্বোচ্চ 10 স্তর পর্যন্ত সঞ্চিত হতে পারে, এবং 10 স্তরে পৌঁছালে হাতে 1টি 「মায়ার সমাপ্তি」 যোগ করুন।"
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "বিলয়ের পথ"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 পর্যায়গুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK ও DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার রাউজ করলে সে [Arg2] কীফ্লেয়ার লাভ করে।\nপ্রতিটি শুঁড়ের আক্রমণ অস্থায়ী শুঁড় ক্ষতি বৃদ্ধি করে তুলুর ATK-এর [Arg3]% পরিমাণে, প্রতি টার্নে সর্বোচ্চ [Arg4] বার পর্যন্ত।\nদলে অন্য 1/2/3 জন 「লেমুরিয়ান」 জাগরণকারী থাকলে, সব শত্রু অতিরিক্ত 10%/25%/50% বেশি শুঁড় ক্ষতি গ্রহণ করে।"
  },
  AwakerTalent_74099_TalentDesc_10 = {
    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 পর্যায়গুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK ও DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার রাউজ করলে সে [Arg2] কীফ্লেয়ার লাভ করে।\nপ্রতিটি শুঁড়ের আক্রমণ অস্থায়ী শুঁড় ক্ষতি বৃদ্ধি করে তুলুর ATK-এর [Arg3]% পরিমাণে, প্রতি টার্নে সর্বোচ্চ [Arg4] বার পর্যন্ত।\nদলে অন্য 1/2/3 জন 「লেমুরিয়ান」 জাগরণকারী থাকলে, সব শত্রু অতিরিক্ত 10%/25%/50% বেশি শুঁড় ক্ষতি গ্রহণ করে।"
