  AwakerTalent_74100_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·「ফেইন্ট」এর শক্তি হ্রাস প্রভাব [Arg4] % বৃদ্ধি পায়।「ফেইন্ট」এর কমান্ড কার্ড খেলার পর, সাময়িকভাবে「মানবাকৃতি」শত্রুর [Arg3]％ ফেইন্ট আক্রমণ শক্তির শক্তি চুরি করে, প্রতি পালায় সর্বাধিক 3 বার কার্যকর।"
  },
