    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·লেক নিজে প্রাপ্ত কালো মুদ্রা [Arg4]％ বৃদ্ধি পায়, ক্রিটিক্যাল হার [Arg3]％ বৃদ্ধি পায়। যদি যুদ্ধের মাধ্যমে কমপক্ষে 400 কালো মুদ্রা অর্জন করা হয়, যুদ্ধ শুরুতে 1 টি「বিশৃঙ্খলার উত্তরাধিকার」আপগ্রেড হয়।"
