    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর হয়।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] ％ বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহার করার পর [Arg2] পয়েন্ট সিলভার কী শক্তি অর্জন করে।\n·「কোলাহলময় সমুদ্র」প্রতি 1টি「গ্রন্থি বিভাজন」খরচ করলে, ওরিটা এই যুদ্ধে পরবর্তীতে যে ক্ষতি করবে তা [Arg3]％ আক্রমণ শক্তি বৃদ্ধি পায়। বস যুদ্ধে যদি「কোলাহলময় সমুদ্র」কমপক্ষে 20টি「গ্রন্থি বিভাজন」খরচ করে,「গ্রন্থি বিভাজন」ব্যবহার ও খরচ হওয়ার সময় ক্ষতির সংখ্যা +1। প্রতি রাউন্ডে প্রথম [Arg4] টি「গ্রন্থি বিভাজন」ব্যবহার করলে「গণনা শক্তি সমন্বয়」যোগ হবে না।"
