  AwakerTalent_74108_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·অগিলের তৈরি ঢাল [Arg3]％ বৃদ্ধি পায়, তৈরি শক্তি [Arg4]％ বৃদ্ধি পায়। প্রতিবার উন্মত্ততা বিস্ফোরণ মুক্ত করার পর এই যুদ্ধে অগিলের তৈরি ঢাল অতিরিক্ত প্রতিরক্ষা শক্তির 1％ বৃদ্ধি পায়।"
  },
