    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 স্তরে কার্যকর।\nঅ্যাওয়েকনারদের CON, আক্রমণ এবং DEF [Arg1] % বৃদ্ধি পায়, এবং প্রথমবার জাগরণের সময় তারা [Arg2] কীফ্লেয়ার লাভ করে।\nযখন তাউইল দলে থাকা অন্য অ্যাওয়েকনারদের মূলত অন্তর্গত কোনো কার্ড ব্যবহার করে, তখন সংশ্লিষ্ট অ্যাওয়েকনারদের এই টার্নে চূড়ান্ত ক্ষতি, শিল্ড এবং HP পুনরুদ্ধার [Arg3] % বৃদ্ধি পায়, এবং এই প্রভাব স্তূপিত হয় না।"
