  AwakerTalent_74120_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·রোটানের কমান্ড কার্ডের মৌলিক ক্ষতি [Arg3]% বৃদ্ধি পায়। রোটান প্রতি 1 বার ক্ষতি করলে, এই পালায় রোটানের চূড়ান্ত ক্ষতি 5% বৃদ্ধি পায়, সর্বাধিক [Arg4]％ বৃদ্ধি।"
  },
