    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·「ক্রমবর্ধমান সুর」খেলার পর সমস্ত「মানবাকৃতি」শত্রুর ক্ষতি সাময়িকভাবে [Arg4]％ হ্রাস পায়, স্তূপীকৃত হয় না।「শান্তির সঙ্গীত」[Arg3] পয়েন্ট উন্মত্ততা পায়, প্রতি 1 টি নেতিবাচক অবস্থা দূর করলে অতিরিক্ত 1 বার পায়।"
