  AwakerTalent_74123_TalentDesc_1 = {
    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 স্তরগুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK এবং DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার রাউজ করলে সে [Arg2] কীফ্লেয়ার লাভ করে।\nএই টার্নে প্রাপ্ত চরিত্রের ঢালের [Arg3]％ সমপরিমাণ মান দ্বারা 「স্ট্রাইক」 এবং 「নির্ভুল আঘাত」-এর মূল ক্ষতি বৃদ্ধি পায়। 「ক্যারো」 রিয়ালমের শত্রুদের প্রতি আলভার প্রদত্ত চূড়ান্ত ক্ষতি [Arg4]％ বৃদ্ধি পায়।"
  },
