  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·লিলির「স্ট্রাইক」চূড়ান্ত ক্ষতি [Arg3]％ বৃদ্ধি পায়, বস যুদ্ধে বৃদ্ধির পরিমাণ দ্বিগুণ।「অতিমাত্রিক」শত্রুর আক্রমণ পাওয়ার পর, এই আক্রমণে হারানো জীবনের [Arg4]％ বিলম্বিত পুনরুদ্ধার প্রভাব পায়।「প্রতিদান স্ট্রাইক」এর「সহনশীলতা」অনুযায়ী ক্ষতি বৃদ্ধি প্রভাব [Arg5]% ক্ষতি শক্তিবৃদ্ধি বোনাস উপভোগ করে।"
  },
