  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] % বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহারের পর [Arg2] পয়েন্ট রৌপ্য চাবি শক্তি পায়।\n·ফালোসের বিষ [Arg3]％ বৃদ্ধি পায়।「হারানো প্রাচীন নগরী」পালা শেষে সমস্ত টেন্টাকলকে 1 বার আক্রমণের আদেশ দেয়, কিন্তু এই আক্রমণগুলো শুধুমাত্র [Arg4]% ক্ষতি করে।\n·যখন দলে 1/2/3 জন অন্য「লিমোরিয়া」জাগ্রত সত্তা থাকে, ক্ষতি শক্তিবৃদ্ধি +20%/50%/100％।"
  },
