  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র「তারকা অধ্যায়」স্তরে কার্যকর হয়।\n·এই জাগ্রত সত্তার সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1] ％ বৃদ্ধি পায়, এবং এই জাগ্রত সত্তা প্রথমবার আধ্যাত্মিক জ্ঞান জাগরণ ব্যবহার করার পর [Arg2] পয়েন্ট সিলভার কী শক্তি অর্জন করে।\n·「ছাই ধ্বংসাবশেষ」রিফ্রেশ হওয়ার সময়, ছাড় প্রদর্শনের সম্ভাবনা [Arg3]％ বৃদ্ধি পায়, ছাড়ের অনুপাত [Arg4]％ বৃদ্ধি পায়।\n·「ঘাড় ভাঙা আঘাত」-এর মৌলিক ক্ষতি [Arg5] ％ বৃদ্ধি পায়, হত্যা থেকে প্রাপ্ত মৌলিক ক্ষতি বৃদ্ধির সাথে স্বতন্ত্রভাবে গণনা করা হয়।"
