  AwakerTalent_78622_TalentDesc_1 = {
    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়「 পর্যায়গুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK এবং DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার Rouse ব্যবহারের সময় তারা [Arg2] Keyflare অর্জন করে।\n「Fiamma「-এর বাফ প্রভাব +[Arg3]%। প্রতিটি টার্নের শুরুতে, কার্ড ফেলে দেওয়ার ধাপের আগে, হাতে থাকা সব কার্ড থেকে 「Burn「 সরিয়ে ফেলো। প্রতিটি 「Burn「 সরানোর জন্য কাথিগু-রা 1 স্তর 「Combust「 অর্জন করে।"
  },
