  AwakerTalent_78624_TalentDesc_1 = {
    Text = "এই প্রতিভা কেবল 「নাক্ষত্রিক অধ্যায় (Astral Reign)」 পর্যায়গুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK এবং DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার Rouse করলে তারা [Arg2] Keyflare পায়।\n「অনিক্স পালক (Onyx Plume)」 বাজালে 「অ্যারিথমেটিকা সামঞ্জস্য (Arithmetica Harmony)」 আর যোগ হয় না। 「পবিত্র পালকের পাপমোচন (Cleansing Feathers)」 দ্বারা সৃষ্ট ক্ষয়কারিতা (Corrosion) Castor-এর ATK-এর [Arg3]% পরিমাণ বাড়ে। 「আলোবাহক (the Lightbearer)」 গির্জার শত্রুদের উপর সৃষ্ট ক্ষয়কারিতা + [Arg4]％।"
  },
