  AwakerTalent_78642_TalentDesc_1 = {
    Text = "·এই প্রতিভা শুধুমাত্র 「তারকা অধ্যায়」 স্তরে কার্যকর হয়।\n·এই অ্যাওয়াকেনারের সংবিধান, আক্রমণ, প্রতিরক্ষা [Arg1]% বৃদ্ধি পায়, এবং এই অ্যাওয়াকেনার প্রথমবার নসিস অ্যাওয়াকেনিং খেলার পর [Arg2] পয়েন্ট সিলভার কী শক্তি অর্জন করে।\n·আরাকনের দ্বারা সৃষ্ট 「ভাগ্যের রায়」 [Arg3]% বৃদ্ধি পায়, মিউট্যান্ট শত্রুদের বিরুদ্ধে 「ভাগ্যের রায়」 দ্বিগুণ হয়।"
  },
