  AwakerTalent_78645_TalentDesc_1 = {
    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 স্তরগুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK এবং DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার রাউজ করলে সে [Arg2] কীফ্লেয়ার লাভ করে।\nসমস্ত জাগরণকারীর অর্জিত শক্তি [Arg3]% বৃদ্ধি পায়।\nক্লেমেন্টাইন যখন 「কীটজাতি」 শত্রুদের ক্ষতি করে, তখন সে প্রদত্ত ক্ষতির [Arg4]% সমপরিমাণ রক্তক্ষরণ প্রভাব আরোপ করে। প্রতি রাউন্ডে প্রথমবার ক্লেমেন্টাইন চরিত্রের ঢাল প্রদান করলে বা HP পুনরুদ্ধার করলে, 「কীটজাতি」 শত্রুরা সাময়িকভাবে ক্লেমেন্টাইনের DEF‑এর [Arg5]% সমপরিমাণ শক্তি হারায়।"
