    Text = "এই প্রতিভা কেবলমাত্র 「নাক্ষত্রিক অধ্যায়」 পর্যায়গুলোতে কার্যকর।\nএই জাগরণকারীর CON, ATK ও DEF [Arg1]% বৃদ্ধি পায়, এবং প্রথমবার রাউজ করলে সে [Arg2] কীফ্লেয়ার লাভ করে।\nযখনই মার্ফি: ফক্সবর্ন ক্ষতি করে, লক্ষ্যবস্তুর ওপর প্রদত্ত ক্ষতির [Arg3]% সমপরিমাণ 「উৎসর্গ」 স্তর আরোপ করো। 「লাইফ সিল」 অবস্থার 「জন্ম আচার」 স্তর-বৃদ্ধি প্রভাব দ্বিগুণ হয়।\nদলে অন্য 1/2/3 জন 「লেমুরিয়ান」 জাগরণকারী থাকলে: সর্বোচ্চ HP +6%/15%/30%; যে কোনো 「লেমুরিয়ান」 জাগরণকারী এক্সাল্ট ব্যবহার করার পর, মার্ফি: ফক্সবর্ন-এর DEF-এর 50%/125%/250% সমপরিমাণ শিল্ড লাভ করো। প্রতি টার্নে একবারের বেশি নয়; শিল্ড উৎপাদন বৃদ্ধির সুবিধা পায় না।"
  },
