  AwakerTalent_79211_TalentDesc_1 = {
    Text = "ক্ষতি করার পর ক্লেমেন্টাইনের কমান্ড কার্ড 1 স্তর 「সহানুভূতি」 অর্জন করে।\nক্লেমেন্টাইন এবং তার সজ্জিত নিয়তিচক্র ও কভেন্যান্ট যে প্রতিটি 1 কীফ্লেয়ার পুনর্জাগরণ বৈশিষ্ট্য প্রদান করে, তা ক্রিটিক্যাল হার এবং ক্রিটিক্যাল ক্ষতি 0.35% করে বৃদ্ধি করে।\nআল্ট্রা রাউন্ডের শুরুতে, সব শত্রুর 「মানসিক আঘাত」 এবং 「ভীতি স্থিরকরণ」 সরিয়ে ফেলো। সব শত্রুর কাছ থেকে সরানো প্রতিটি 「মানসিক আঘাত」 স্তরের জন্য 50 কীফ্লেয়ার অর্জন করো; সব শত্রুর কাছ থেকে সরানো প্রতিটি 「ভীতি স্থিরকরণ」 স্তরের জন্য, অন্যান্য অওয়েকেনাররা 2 আলিয়েমাস পায়।"
  },
