  AwakerTalent_84132_TalentDesc_1 = {
    Text = "·ওরেটার প্রতি 1 পয়েন্ট উন্মাদনা রিচার্জ স্তরে, যুদ্ধ শুরুতে ওরেটার আক্রমণ শক্তির 2％ শুঁড় ক্ষতি অর্জন করে, প্রতি 1％ ক্রিটিক্যাল হারে, যুদ্ধ শুরুতে ওরেটার আক্রমণ শক্তির 1％ শুঁড় ক্ষতি অর্জন করে।"
  },
  AwakerTalent_84132_TalentName_1 = {
