  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·প্রতি রাউন্ডে প্রথমবার 「কালো পালক」 খেলার সময় সমস্ত শত্রুদের উপর নিজের আক্রমণ শক্তির 840％ 「ক্ষয়」 প্রয়োগ করে এবং 10 পয়েন্ট উন্মাদনা অর্জন করে।\n·ক্যাস্টরের প্রতি 1％ ক্ষতি শক্তিবৃদ্ধি মূল 「ক্ষয়」 1％ বৃদ্ধি করে।\n·যুদ্ধ শেষ হওয়ার পর, এই অনুসন্ধানে ক্যাস্টরের প্রয়োগকৃত 「ক্ষয়」 স্থায়ীভাবে 20％ বৃদ্ধি পায়।\n·বস যুদ্ধে প্রয়োগকৃত 「ক্ষয়」 দ্বিগুণ হয়।\n·ক্যাস্টর 「ক্ষয়」 প্রয়োগের পর এই রাউন্ডে নিজের ক্ষতি প্রয়োগ পরিমাণের 5％ বৃদ্ধি পায়।\n·ক্যাস্টরের করা ক্ষতি 「ক্ষয়」 অপসারণ করে না।"
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "পবিত্র পালকের পাপমোচন"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "ডোরেসেইন কোনো শত্রুকে হত্যা করার পর বা কোনো বসের ওপর এক্সাল্ট ডিএমজি প্রয়োগ করলে 1টি 「ধ্বংসাবশেষ」 সঞ্চয় করে।\nসে সর্বোচ্চ 3 স্তর সংখ্যা 「ধ্বংসাবশেষ」 ধরে রাখতে পারে, যা পুরো অনুসন্ধান জুড়ে ধরে রাখো হয়।"
