  AwakerTalent_97268_TalentDesc_1 = {
    Text = "ডোরেসেইন একটি 「ধ্বংসাবশেষ」 অর্জন করার পর, হাতে ১টি \"চিররাত্রির উৎসব\" যোগ করো।"
  },
  AwakerTalent_97268_TalentName_1 = {
    Text = "পচনশীল কৃপা"
  },
  AwakerTalent_98451_TalentDesc_1 = {
    Text = "টার্নের শুরুতে, এলোমেলোভাবে হাতে থাকা কাথিগু-রার 1টি কমান্ড কার্ডে 「ফিয়াম্মা「‑র 1 স্তর সংখ্যা প্রয়োগ করো।\nকাথিগু-রা দ্বারা ভোগ করা প্রতিটি 「ফিয়াম্মা「 স্তর সংখ্যার জন্য, 1 স্তর সংখ্যা 「প্রজ্বলন「 অর্জন করো।\n「প্রজ্বলন「 10 স্তর সংখ্যায় পৌঁছালে, 2টি অ্যারিথমেটিকা অর্জন করো এবং সব <Blue:সোলারফ্লেয়ার>‑কে <Blue:হাইপারফ্লেয়ার>‑এ উন্নয়ন অর্জন করো।"
  },
  AwakerTalent_98451_TalentName_1 = {
    Text = "বিস্ফোরণের প্রভু"
  },
  AwakerTalent_98714_TalentDesc_1 = {
    Text = "প্যান্ডিয়া বা তার নিয়তিচক্র ও কভেন্যান্ট যে প্রতি ১% ক্রিট. রেট প্রদান করে, তার জন্য সে যে স্থায়ী কাউন্টার তৈরি করে তা +০.২% বৃদ্ধি পায়।"
  },
  AwakerTalent_98714_TalentName_1 = {
    Text = "শাস্তির সময়"
  },
  AwakerTalent_99107_TalentDesc_1 = {
    Text = "পিকম্যান \"আবিষ্কার\" প্রভাব সক্রিয় করার পর বা \"ক্রোমাফেজ\" ব্যবহার করলে, সে \"সৃজনশীলতা\"র ১ স্তর সংখ্যা অর্জন করে।"
  },
